// Build embed text for each entity
const teams = $('Fetch teams missing embeddings').first().json;
const participants = $('Fetch participants missing embeddings').first().json;
const mentors = $('Fetch mentors missing embeddings').first().json;

const toEmbed = (arr) => Array.isArray(arr) ? arr : [];

const items = [];

for (const t of toEmbed(teams)) {
  const text = [t.name, t.challenge, t.project_idea, t.goals, ...(t.needed_roles || [])].filter(Boolean).join(' ');
  items.push({ id: t.id, table: 'teams', text });
}

for (const p of toEmbed(participants)) {
  const skills = Array.isArray(p.skills) ? p.skills.map(s => typeof s === 'string' ? s : s.name).join(' ') : '';
  const roles = Array.isArray(p.roles) ? p.roles.join(' ') : '';
  const interests = Array.isArray(p.interests) ? p.interests.join(' ') : '';
  const text = [p.name, p.bio, skills, roles, interests].filter(Boolean).join(' ');
  items.push({ id: p.id, table: 'participants', text });
}

for (const m of toEmbed(mentors)) {
  const expertise = Array.isArray(m.expertise) ? m.expertise.join(' ') : '';
  const text = [m.name, expertise, m.experience].filter(Boolean).join(' ');
  items.push({ id: m.id, table: 'mentors', text });
}

// Chunk into batches of 50
const batches = [];
for (let i = 0; i < items.length; i += 50) {
  batches.push(items.slice(i, i + 50));
}

return batches.map(batch => ({ json: { batch } }));

