// Write embeddings back to Supabase
const batch = $('Build embed text + batch').first().json.batch;
const embeddings = $input.first().json.embeddings || [];

const results = { teams: 0, participants: 0, mentors: 0, errors: 0 };
const supabaseUrl = $env.SUPABASE_URL;

for (let i = 0; i < batch.length; i++) {
  const item = batch[i];
  const embedding = embeddings[i]?.values;
  if (!embedding) { results.errors++; continue; }

  try {
    const res = await this.helpers.httpRequest({
      method: 'PATCH',
      url: `${supabaseUrl}/rest/v1/${item.table}?id=eq.${item.id}`,
      headers: {
        'Content-Type': 'application/json',
        'Prefer': 'return=minimal',
      },
      body: JSON.stringify({ embedding: JSON.stringify(embedding) }),
      returnFullResponse: false,
    });
    results[item.table]++;
  } catch (e) {
    results.errors++;
  }
}

return [{ json: { summary: `Embedded: ${results.teams} teams, ${results.participants} participants, ${results.mentors} mentors. Errors: ${results.errors}` } }];
